        self._finish_event(start, len(name) + 3)

    def handle_comment(self, data: str) -> None:
        start = self._copy_to_event()
        end = self.rawdata.find("-->", start + 4)
        length = len(self.rawdata) - start if end == -1 else end + 3 - start
        self._finish_event(start, length)

    def handle_decl(self, decl: str) -> None:
        start = self._copy_to_event()
        end = self.rawdata.find(">", start) + 1
        self._finish_event(start, end - start)

    def handle_pi(self, data: str) -> None:
        start = self._copy_to_event()
        end = self.rawdata.find(">", start) + 1
        self._finish_event(start, end - start)

    def unknown_decl(self, data: str) -> None:
        start = self._copy_to_event()
        end = self.rawdata.find("]>", start) + 2
        self._finish_event(start, end - start)

    def result(self) -> str:
        if self._script_depth == 0:
            self._output.append(self.rawdata[self._cursor:])
        return "".join(self._output)

    def set_cdata_mode(self, elem: str, escapable: bool = False) -> None:
        if elem != "script":
            super().set_cdata_mode(elem, escapable=escapable)


def sanitize(html: str) -> str:
    parser = _ScriptStripper()
    parser.feed(html)
    parser.close()
    return parser.result()
